      {"name": "Starter", "price": "$29/month", "billing": "monthly (annual saves ~20%)", "features": ["Unlimited email coaching", "AI writer", "Core integrations"]},
      {"name": "Individual Pro", "price": "$49/month", "billing": "monthly (annual saves ~20%)", "features": ["Everything in Starter", "Advanced personalization", "Deeper prospect insights"]},
