                    {"name": "Pro", "price": "$20/mo", "billing": "Monthly, individual", "features": ["Agent-native, multi-platform experience (Desktop/CLI/SDK)", "Cloud and local background agents", "Billing and usage statistics tracking", "Agent-readiness dashboard"]},
                    {"name": "Plus", "price": "$100/mo", "billing": "Monthly, individual", "features": ["Everything in Pro", "~5x the rolling usage of Pro", "Droid Computers — Factory-managed cloud compute for remote Droids"]},
                    {"name": "Max", "price": "$200/mo", "billing": "Monthly, individual", "features": ["Everything in Plus", "~10x the rolling usage of Pro", "Early access to new features"]},
