                    {"name": "Commitment Tiers & Volume Discounts", "price": "Custom, quote-based", "billing": "Monthly commitment with overage billed per million characters", "features": ["Discounted rates at 250M / 1B / 4B+ characters per month", "Separate C2-C4 tiers for high-volume Custom Translation", "Connected/disconnected container options"]},
                    {"name": "On-Premises Enterprise Edition", "price": "$310,000/year (list)", "billing": "12-month subscription, volume pricing available", "features": ["Design, deployment, and updates included", "Fully on-premises runtime engine", "For regulated, sovereignty-restricted, or air-gapped organizations"]}
