                    {"name": "Starter", "price": "$20/mo per seat", "billing": "~$15/mo per seat if billed annually", "features": ["Breeze Copilot and basic AI content assistance", "Marketing/Sales/Service Starter feature sets", "Simple automation"]},
                    {"name": "Professional", "price": "From ~$800-890/mo", "billing": "Billed annually; price and included seats/contacts vary significantly by Hub", "features": ["Breeze Agents for content and prospecting workflows", "Predictive lead scoring", "More AI credits and advanced automation"]},
                    {"name": "Enterprise", "price": "From ~$3,600/mo", "billing": "Billed annually; varies by Hub", "features": ["Full Breeze Agents suite", "Breeze Intelligence data enrichment at scale", "Custom AI workflows and advanced permissions"]},
