                    {"name": "Starter", "price": "From $47/month", "billing": "Monthly, 14-day free trial", "features": ["No-code flow builder", "CRM integrations", "Lead scoring", "Ad conversion tracking"]},
                    {"name": "Growth/Scale", "price": "Up to $1,000/month", "billing": "Monthly, scales with traffic/features", "features": ["Higher traffic and conversation volume", "Advanced integrations", "Priority support", "Full analytics dashboard"]}
