                    {"name": "Pro", "price": "$99.99/mo", "billing": "monthly", "features": ["Large compute point pool for power users and small teams", "Priority access during high-demand periods"]},
                    {"name": "Pro Max", "price": "$249.99/mo", "billing": "monthly", "features": ["~8.25 million monthly compute points", "Built for high-volume, professional usage", "Developer API access"]}
