                    {"name": "Hobbyist", "price": "$24/mo", "billing": "$16/mo billed annually; 1 seat included", "features": ["10 media hours/month", "400 AI credits/month", "1080p export, watermark-free", "Access to Underlord and core AI tools", "100GB cloud storage"]},
                    {"name": "Creator", "price": "$35/mo", "billing": "$24/mo billed annually (most popular); scales to a team of 3", "features": ["30 media hours/month", "800 AI credits/month", "4K export, watermark-free", "Full Underlord + 20 more AI tools", "1TB cloud storage"]},
                    {"name": "Business", "price": "$65/mo", "billing": "$50/mo billed annually; scales to a team of 5", "features": ["40 media hours/month", "1,500 AI credits/month", "Team-wide Brand Studio", "Translate/dub in 30+ languages with proofread", "2TB cloud storage"]},
                    {"name": "Enterprise", "price": "Custom pricing", "billing": "Contact sales", "features": ["AI credits and media hours sized to your team", "SOC 2 Type II, SSO, SCIM, audit logs", "Dedicated CSM and priority support"]},
