      {"name": "Standard", "price": "$12/month", "billing": "Monthly (yearly saves 20%)", "features": ["Everything in Free", "Unlimited projects and REST API integrations", "Full code editing and export", "1-click publishing to iOS, Android, and web", "Custom domains, remove Draftbit branding", "Editor seats add-on at $8/seat/mo"]},
      {"name": "Pro", "price": "$24/month", "billing": "Monthly (yearly saves 20%), most popular", "features": ["Everything in Standard", "Up to 3 concurrent sandboxes, run up to 5 agents at once", "Custom MCP server integrations", "Export to GitHub", "iOS & Android simulators, larger/faster sandboxes", "App Store submission assistance, priority support"]},
      {"name": "Team", "price": "$120/month", "billing": "Monthly (yearly saves 20%)", "features": ["Everything in Pro", "10 editor seats included, up to 5 concurrent sandboxes", "Live collaboration features, run up to 10 agents at once", "Team training sessions, dedicated account manager"]},
      {"name": "Enterprise", "price": "Custom", "billing": "Custom annual pricing", "features": ["Unlimited sandboxes, editor seats, and concurrent agents", "SSO/SAML authentication, custom SLAs", "Dedicated infrastructure, private/self-hosting options", "Custom integrations and dedicated success manager"]}
