# ---------- data wiring ----------

def slugify(s):
    return re.sub(r"[^a-z0-9]+", "-", s.lower()).strip("-")

ALL_TOOLS = []
for cat in CATEGORIES:
    for t in cat["tools"]:
        t["category"] = cat["name"]
        t["cat_slug"] = cat["slug"]
        t["slug"] = slugify(t["name"])
        ALL_TOOLS.append(t)

def stagger(i, cap=8, step=0.06):
    return round(min(i, cap) * step, 2)

TOOLS_BY_NAME = {t["name"]: t for t in ALL_TOOLS}

def rating_display(t):
    r = t.get("deep", {}).get("reviews")
    if not r:
        return None
    for src, label in (("g2", "G2"), ("capterra", "Capterra"), ("app_store", "App Store"), ("chrome_store", "Chrome Web Store")):
        val = r.get(f"{src}_rating")
        if val:
            count = r.get(f"{src}_count", "")
            return f"{label} {val}" + (f" ({count})" if count else "")
    return None

# ---------- structured data (JSON-LD) for SEO / AEO ----------

def _parse_rating(s):
    if not s:
        return None
    m = re.search(r"[\d.]+", s)
    return float(m.group()) if m else None

def _parse_count(s):
    if not s:
        return 0
    m = re.search(r"\d[\d,]*", s)
    return int(m.group().replace(",", "")) if m else 0

def _script(data):
    return f'<script type="application/ld+json">{json.dumps(data, ensure_ascii=False)}</script>'

def org_website_jsonld():
    org = {
        "@context": "https://schema.org", "@type": "Organization",
        "name": SITE_NAME, "url": f"{SITE_URL}/index.html",
        "description": SITE_DESC,
    }
    website = {
        "@context": "https://schema.org", "@type": "WebSite",
        "name": SITE_NAME, "url": f"{SITE_URL}/index.html",
        "description": SITE_DESC,
        "potentialAction": {
            "@type": "SearchAction",
            "target": {"@type": "EntryPoint", "urlTemplate": f"{SITE_URL}/all-tools.html?q={{search_term_string}}"},
            "query-input": "required name=search_term_string",
        },
    }
    return _script(org) + "\n" + _script(website)

def tool_jsonld(t, cat):
    d = t.get("deep")
    page_url = f"{SITE_URL}/tools/{t['slug']}.html"
    software = {
        "@context": "https://schema.org", "@type": "SoftwareApplication",
        "name": t["name"], "description": t["desc"], "url": t["url"],
        "applicationCategory": cat["name"], "operatingSystem": "Web",
    }
    graph_scripts = []
    if d:
        r = d.get("reviews") or {}
        g2, cap = _parse_rating(r.get("g2_rating")), _parse_rating(r.get("capterra_rating"))
        ratings = [x for x in (g2, cap) if x]
        if ratings:
            count = _parse_count(r.get("g2_count")) + _parse_count(r.get("capterra_count"))
            software["aggregateRating"] = {
                "@type": "AggregateRating",
                "ratingValue": round(sum(ratings) / len(ratings), 1),
                "bestRating": "5", "worstRating": "1",
                "ratingCount": max(count, 1),
            }
        if d.get("pricing_plans"):
            offers = []
            for p in d["pricing_plans"]:
                m = re.search(r"[\d][\d,.]*", p["price"])
                offers.append({
                    "@type": "Offer", "name": p["name"], "priceCurrency": "USD",
                    "price": m.group().replace(",", "") if m else "0",
                    "description": p.get("billing", ""),
                })
            software["offers"] = offers
    graph_scripts.append(_script(software))
    if d and d.get("faq"):
        faqpage = {
            "@context": "https://schema.org", "@type": "FAQPage",
            "mainEntity": [
                {"@type": "Question", "name": qa["q"],
                 "acceptedAnswer": {"@type": "Answer", "text": qa["a"]}}
                for qa in d["faq"]
            ],
        }
        graph_scripts.append(_script(faqpage))
    breadcrumb = {
        "@context": "https://schema.org", "@type": "BreadcrumbList",
        "itemListElement": [
            {"@type": "ListItem", "position": 1, "name": "Home", "item": f"{SITE_URL}/index.html"},
            {"@type": "ListItem", "position": 2, "name": cat["name"], "item": f"{SITE_URL}/categories/{cat['slug']}.html"},
            {"@type": "ListItem", "position": 3, "name": t["name"], "item": page_url},
        ],
    }
    graph_scripts.append(_script(breadcrumb))
    return "\n".join(graph_scripts)

# ---------- shared chrome ----------

def nav(depth=0):
    prefix = "../" if depth else ""
    return f"""
<div class="cursor-ring" id="cursorRing"></div>
<header class="site-header" id="siteHeader">
  <div class="container nav-wrap">
    <a class="logo" href="{prefix}index.html">{SITE_NAME}</a>
    <nav class="main-nav" id="mainNav">
      <a href="{prefix}index.html">Home</a>
      <a href="{prefix}all-tools.html">All Tools</a>
      <a href="{prefix}blog/index.html">Blog</a>
      <a href="{prefix}submit-tool.html">Submit a Tool</a>
      <a href="{prefix}about.html">About</a>
    </nav>
    <button class="nav-toggle" id="navToggle" aria-label="Toggle menu">&#9776;</button>
  </div>
</header>
"""

def footer(depth=0):
    prefix = "../" if depth else ""
    cat_links = "\n".join(
        f'<a href="{prefix}categories/{c["slug"]}.html">{c["name"]}</a>' for c in CATEGORIES
    )
    return f"""
<footer class="site-footer reveal">
  <div class="container footer-grid">
    <div>
      <div class="logo">{SITE_NAME}</div>
      <p class="muted">{SITE_DESC}</p>
    </div>
    <div>
      <h4>Categories</h4>
      <div class="footer-links">{cat_links}</div>
    </div>
    <div>
      <h4>Compare</h4>
      <div class="footer-links">
        <a href="{prefix}compare.html">Compare AI Tools</a>
      </div>
    </div>
    <div>
      <h4>Site</h4>
      <div class="footer-links">
        <a href="{prefix}blog/index.html">Blog</a>
        <a href="{prefix}about.html">About</a>
        <a href="{prefix}submit-tool.html">Submit a Tool</a>
      </div>
    </div>
  </div>
  <div class="container disclosure">
    <p class="muted small">Affiliate disclosure: some links on {SITE_NAME} are affiliate links. We may earn a commission if you sign up through them, at no extra cost to you. This never affects which tools we choose to list.</p>
    <p class="muted small">&copy; 2026 {SITE_NAME}. All product names and logos are property of their respective owners.</p>
  </div>
</footer>
"""

def page(title, description, body, depth=0, extra_head="", url_path=""):
    prefix = "../" if depth else ""
    canonical = f"{SITE_URL}/{url_path}" if url_path else SITE_URL
    return f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>{title}</title>
<meta name="description" content="{description}">
<link rel="canonical" href="{canonical}">
<meta property="og:title" content="{title}">
<meta property="og:description" content="{description}">
<meta property="og:type" content="website">
<meta property="og:url" content="{canonical}">
<meta name="twitter:card" content="summary">
<meta name="twitter:title" content="{title}">
<meta name="twitter:description" content="{description}">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Fraunces:ital,wght@1,400;1,500&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
<link rel="stylesheet" href="{prefix}assets/style.css">
{extra_head}
</head>
<body>
{nav(depth)}
<main>
{body}
</main>
{footer(depth)}
<script src="{prefix}assets/script.js"></script>
</body>
</html>"""

def tool_card(t, depth=0, index=0):
    prefix = "../" if depth else ""
    tags = "".join(f'<span class="tag">{tag}</span>' for tag in t["tags"])
    cat_link = f'{prefix}categories/{t["cat_slug"]}.html'
    tool_link = f'{prefix}tools/{t["slug"]}.html'
    d = stagger(index)
    return f"""
<article class="tool-card reveal tilt" data-category="{t['cat_slug']}" data-name="{t['name'].lower()}" style="transition-delay:{d}s">
  <div class="tool-card-top">
    <h3><a href="{tool_link}">{t['name']}</a></h3>
    <a class="cat-label" href="{cat_link}">{t['category']}</a>
  </div>
  <p class="tool-tagline">{t['tagline']}</p>
  <p class="tool-desc">{t['desc']}</p>
  <p class="tool-pricing"><strong>Pricing</strong> {t['pricing']}</p>
  <div class="tags">{tags}</div>
  <div class="card-actions">
    <a class="btn btn-primary magnetic" href="{tool_link}">More details <span class="arrow">&rarr;</span></a>
    <a class="text-link" href="{t['url']}" target="_blank" rel="noopener sponsored">Visit website <span class="arrow">&rarr;</span></a>
  </div>
</article>
"""

def category_card(cat, depth=0, index=0):
    prefix = "../" if depth else ""
    d = stagger(index)
    num = str(index + 1).zfill(2)
    return f"""
<a class="category-card reveal tilt" href="{prefix}categories/{cat['slug']}.html" style="transition-delay:{d}s">
  <div class="cat-num">{num}</div>
  <div class="cat-icon">{cat['icon']}</div>
  <h3>{cat['name']}</h3>
  <p class="muted">{cat['short']}</p>
  <span class="cat-count">{len(cat['tools'])} tools <span class="arrow">&rarr;</span></span>
</a>
"""

