def tool_detail_body(t, cat, depth=1):
    prefix = "../" if depth else ""
    d = t.get("deep")
    others = [o for o in cat["tools"] if o["slug"] != t["slug"]]
    alt_html = "".join(
        f'<a class="alt-card reveal tilt" href="{prefix}tools/{o["slug"]}.html" style="transition-delay:{stagger(i)}s">'
        f'<h4>{o["name"]}</h4><p class="muted">{o["tagline"]}</p><span class="text-link">Compare <span class="arrow">&rarr;</span></span></a>'
        for i, o in enumerate(others)
    )

    hero = f"""
<section class="container section page-hero tool-hero">
  <div class="breadcrumb reveal">
    <a href="{prefix}index.html">Home</a> <span>/</span>
    <a href="{prefix}categories/{cat['slug']}.html">{cat['name']}</a> <span>/</span>
    <span>{t['name']}</span>
  </div>
  <div class="tool-hero-top">
    <div>
      <div class="kicker reveal">{cat['name']}</div>
      <h1 class="reveal" style="transition-delay:.08s">{t['name']}</h1>
      <p class="hero-sub-left reveal" style="transition-delay:.16s">{t['tagline']}</p>
"""
    if d and d.get("reviews"):
        r = d["reviews"]
        chips = ""
        if r.get("g2_rating"):
            chips += f'<span class="rating-chip">G2 <strong>{r["g2_rating"]}</strong> <span class="muted">({r.get("g2_count","")})</span></span>'
        if r.get("capterra_rating"):
            chips += f'<span class="rating-chip">Capterra <strong>{r["capterra_rating"]}</strong> <span class="muted">({r.get("capterra_count","")})</span></span>'
        if r.get("app_store_rating"):
            chips += f'<span class="rating-chip">App Store <strong>{r["app_store_rating"]}</strong> <span class="muted">({r.get("app_store_count","")})</span></span>'
        if r.get("chrome_store_rating"):
            chips += f'<span class="rating-chip">Chrome Web Store <strong>{r["chrome_store_rating"]}</strong> <span class="muted">({r.get("chrome_store_count","")})</span></span>'
        if chips:
            hero += f"""      <div class="rating-row reveal" style="transition-delay:.2s">
        {chips}
      </div>
"""
    hero += f"""    </div>
    <div class="tool-hero-cta reveal" style="transition-delay:.24s">
      <div class="price-tag">{t['pricing']}</div>
      <a class="btn btn-primary magnetic" href="{t['url']}" target="_blank" rel="noopener sponsored">Visit {t['name']} <span class="arrow">&rarr;</span></a>
    </div>
  </div>
</section>
"""

    best_for_short = t['best_for'] if not d else d['who_for'].split('. ')[0].strip().rstrip('.') + '.'
    quick_facts = f"""
<section class="container section narrow" style="padding-top:0;">
  <dl class="quick-facts reveal">
    <div class="qf-item"><dt>Category</dt><dd><a href="{prefix}categories/{cat['slug']}.html">{cat['name']}</a></dd></div>
    <div class="qf-item"><dt>Pricing</dt><dd>{t['pricing']}</dd></div>
    <div class="qf-item"><dt>Best for</dt><dd>{best_for_short}</dd></div>
    <div class="qf-item"><dt>Official site</dt><dd><a href="{t['url']}" target="_blank" rel="noopener sponsored">{t['url'].replace('https://', '').replace('http://', '').rstrip('/')}</a></dd></div>
    <div class="qf-item"><dt>Last updated</dt><dd>{LAST_UPDATED}</dd></div>
  </dl>
</section>
"""

    if not d:
        features_html = "".join(f'<li class="reveal" style="transition-delay:{stagger(i,4,0.05)}s"><span class="check">&#10003;</span>{feat}</li>' for i, feat in enumerate(t["features"]))
