def blog_jsonld(post):
    page_url = f"{SITE_URL}/blog/{post['slug']}.html"
    article = {
        "@context": "https://schema.org", "@type": "Article",
        "headline": post["title"], "description": post["meta_description"],
        "url": page_url, "datePublished": "2026-08-07", "dateModified": "2026-08-07",
        "author": {"@type": "Organization", "name": SITE_NAME, "url": f"{SITE_URL}/index.html"},
        "publisher": {"@type": "Organization", "name": SITE_NAME},
    }
    graph_scripts = [_script(article)]
    if post.get("faq"):
        faqpage = {
            "@context": "https://schema.org", "@type": "FAQPage",
            "mainEntity": [
                {"@type": "Question", "name": qa["q"], "acceptedAnswer": {"@type": "Answer", "text": qa["a"]}}
                for qa in post["faq"]
            ],
        }
        graph_scripts.append(_script(faqpage))
    breadcrumb = {
        "@context": "https://schema.org", "@type": "BreadcrumbList",
        "itemListElement": [
            {"@type": "ListItem", "position": 1, "name": "Home", "item": f"{SITE_URL}/index.html"},
            {"@type": "ListItem", "position": 2, "name": "Blog", "item": f"{SITE_URL}/blog/index.html"},
            {"@type": "ListItem", "position": 3, "name": post["title"], "item": page_url},
        ],
    }
    graph_scripts.append(_script(breadcrumb))
    return "\n".join(graph_scripts)

def blog_post_body(post, depth=1):
    prefix = "../" if depth else ""
    opp_name = post["opponent_name"]
    opp_url_local = f"{prefix}tools/{post['opponent_slug']}.html"
    pl_url_local = f"{prefix}tools/{PAGELENS['slug']}.html"

    rows_html = "".join(
        f'<tr><td>{r["label"]}</td><td class="pl-col">{r["pagelens"]}</td><td>{r["opponent"]}</td></tr>'
        for r in post["compare_rows"]
    )

    sections_html = "".join(
        f'<h2 class="reveal">{s["h2"]}</h2>' + "".join(f'<p class="reveal">{p}</p>' for p in s["paragraphs"])
        for s in post["sections"]
    )

    why_html = "".join(f'<li class="reveal"><span class="check">&#10003;</span>{w}</li>' for w in post["why_pagelens"])

    faq_html = "".join(
        f'<div class="faq-item reveal" style="transition-delay:{stagger(i,6,0.05)}s"><h4>{qa["q"]}</h4><p class="muted">{qa["a"]}</p></div>'
        for i, qa in enumerate(post["faq"])
    )

    other_posts = [p for p in BLOG_POSTS if p["slug"] != post["slug"]]
    other_html = "".join(
        f'<a class="alt-card reveal tilt" href="{prefix}blog/{p["slug"]}.html" style="transition-delay:{stagger(i)}s">'
        f'<h4>{p["opponent_name"]} vs PageLens.ai</h4><p class="muted">{p["dek"]}</p><span class="text-link">Read comparison <span class="arrow">&rarr;</span></span></a>'
        for i, p in enumerate(other_posts)
    )

    return f"""
<section class="container section narrow page-hero">
  <div class="breadcrumb reveal">
    <a href="{prefix}index.html">Home</a> <span>/</span>
    <a href="{prefix}blog/index.html">Blog</a> <span>/</span>
    <span>{opp_name} vs PageLens.ai</span>
  </div>
  <div class="kicker reveal">Comparison</div>
  <h1 class="reveal" style="transition-delay:.08s">{post['title']}</h1>
  <p class="hero-sub-left reveal" style="transition-delay:.16s">{post['dek']}</p>
</section>

<section class="container section narrow" style="padding-top:0;">
  <div class="verdict-box reveal">
    <span class="winner-tag">Our pick: PageLens.ai</span>
    <p>{post['verdict']}</p>
  </div>
</section>

<section class="container section" style="padding-top:0;">
  <h2 class="reveal">{opp_name} vs PageLens.ai at a glance</h2>
  <div class="table-wrap reveal">
    <table class="compare-table">
      <thead><tr><th>Criterion</th><th>PageLens.ai</th><th>{opp_name}</th></tr></thead>
      <tbody>{rows_html}</tbody>
    </table>
  </div>
</section>

<section class="container section narrow" style="padding-top:0;">
  {sections_html}
</section>

<section class="container section narrow" style="padding-top:0;">
  <h2 class="reveal">Why teams choose PageLens.ai over {opp_name}</h2>
  <ul class="feature-list">{why_html}</ul>
</section>

<section class="container section narrow" style="padding-top:0;">
  <div class="callout reveal">
    <div class="callout-label">In fairness to {opp_name}</div>
    <p>{post['fair_callout']}</p>
  </div>
</section>

<section class="container section narrow" style="padding-top:0;">
  <h2 class="reveal">Frequently asked questions</h2>
  <div class="faq-list">{faq_html}</div>
</section>

<section class="container section" style="padding-top:0;">
  <h2 class="reveal">More PageLens.ai comparisons</h2>
  <div class="alt-grid">{other_html}</div>
</section>

<section class="container section cta-band reveal">
  <h2>See your own AI visibility first</h2>
  <p class="muted">Run a free, 30-second audit to see how ChatGPT, Claude, Gemini and Perplexity currently describe your brand &mdash; no signup required.</p>
  <a href="{PAGELENS['url']}" target="_blank" rel="noopener sponsored" class="btn btn-primary magnetic">Try PageLens.ai free <span class="arrow">&rarr;</span></a>
  <p class="muted small" style="margin-top:16px;">Read the full <a href="{pl_url_local}">PageLens.ai review</a> or the full <a href="{opp_url_local}">{opp_name} review</a> on {SITE_NAME}.</p>
</section>
"""

for post in BLOG_POSTS:
    body = blog_post_body(post, depth=1)
    with open(os.path.join(BLOG_DIR, f"{post['slug']}.html"), "w") as f:
        f.write(page(post["title"], post["meta_description"], body, depth=1, extra_head=blog_jsonld(post), url_path=f"blog/{post['slug']}.html"))

